import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  ChevronLeft, Calendar, User, MapPin, Clock, 
  MoreVertical, Search, Layers, ChevronDown, Plus, Minus,
  Monitor, Mic, Video, Tablet, Edit3, Camera, X, PlusSquare
} from 'lucide-react';
import './MeetingRoom.css';

const MeetingRoom = () => {
  const navigate = useNavigate();
  
  // 视图状态控制
  const [view, setView] = useState('list'); 
  const [selectedRoom, setSelectedRoom] = useState(null);
  const [attendees, setAttendees] = useState(0);

  // --- 新增：分类标签状态 ---
  const [activeTab, setActiveTab] = useState('All'); // 'All', 'Today', 'Week'

  // --- 新增：模拟会议数据 ---
  const meetingsData = [
    { id: 1, title: "UAT Briefing", host: "ALAN TAN WAI LOON", room: "Idea Lab 6", date: "2026-02-10", time: "12:00 PM - 12:30 PM", attendees: 1 },
    { id: 2, title: "Design Sync", host: "ALAN TAN WAI LOON", room: "Idea Lab 2", date: "2026-02-10", time: "02:00 PM - 03:00 PM", attendees: 3 },
    { id: 3, title: "Weekly Review", host: "ALAN TAN WAI LOON", room: "Idea Lab 5", date: "2026-02-12", time: "10:00 AM - 11:30 AM", attendees: 5 },
    { id: 4, title: "Project Launch", host: "ALAN TAN WAI LOON", room: "Idea Lab 1", date: "2026-02-20", time: "09:00 AM - 10:00 AM", attendees: 10 }
  ];

  // 日历与时间逻辑状态
  const [isCalendarOpen, setIsCalendarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState(new Date(2026, 1, 10)); // 默认设为今天 2026-02-10
  const [viewDate, setViewDate] = useState(new Date(2026, 1, 1)); 

  // 下拉选择状态
  const [selectedStartTime, setSelectedStartTime] = useState('');
  const [selectedEndTime, setSelectedEndTime] = useState('');
  const [selectedDuration, setSelectedDuration] = useState('');
  const [selectedFloor, setSelectedFloor] = useState('');

  // 预约表单详情状态
  const [meetingTitle, setMeetingTitle] = useState('');
  const [appointmentType, setAppointmentType] = useState('');
  const [selectedParticipants, setSelectedParticipants] = useState([]);

  // 外部参与者 Modal 状态
  const [isExtModalOpen, setIsExtModalOpen] = useState(false);
  const [extName, setExtName] = useState('');
  const [extEmail, setExtEmail] = useState('');

  const allFeatures = ["Projector", "Interactive TV", "Non-Interactive TV", "180° Camera", "Conference Camera", "Tabletop Teams Panel", "Wireless Mic"];

  // --- 过滤逻辑 ---
  const filteredMeetings = meetingsData.filter(meeting => {
    const today = "2026-02-10"; // 固定当前日期用于演示
    if (activeTab === 'Today') return meeting.date === today;
    if (activeTab === 'Week') {
      // 简单逻辑：假设本周是 2026-02-09 到 2026-02-15
      return meeting.date >= "2026-02-09" && meeting.date <= "2026-02-15";
    }
    return true; // List All
  });

  // 时间生成逻辑
  const fromTimeSlots = [];
  for (let hour = 10; hour <= 17; hour++) {
    const period = hour < 12 ? 'AM' : 'PM';
    const displayHour = hour > 12 ? hour - 12 : hour;
    fromTimeSlots.push(`${displayHour}:00 ${period}`);
    if (hour !== 17) fromTimeSlots.push(`${displayHour}:30 ${period}`);
  }

  const getToTimeSlots = () => {
    if (!selectedStartTime) return [];
    const list = [];
    const [time, period] = selectedStartTime.split(' ');
    let [h, m] = time.split(':').map(Number);
    if (period === 'PM' && h !== 12) h += 12;
    if (period === 'AM' && h === 12) h = 0;
    const startNum = h + (m / 60) + 0.5;
    for (let i = startNum; i <= 20; i += 0.5) {
      const p = i < 12 ? 'AM' : 'PM';
      let dh = Math.floor(i);
      if (dh > 12) dh -= 12;
      const dm = (i % 1) === 0 ? "00" : "30";
      list.push(`${dh}:${dm} ${p}`);
    }
    return list;
  };

  const getAvailableDurations = () => {
    if (!selectedStartTime) return [];
    const [time, period] = selectedStartTime.split(' ');
    let [h, m] = time.split(':').map(Number);
    if (period === 'PM' && h !== 12) h += 12;
    if (period === 'AM' && h === 12) h = 0;
    const startNum = h + (m / 60);
    const maxAllowed = 20 - startNum; 
    const list = [];
    for (let i = 0.5; i <= Math.min(5, maxAllowed); i += 0.5) {
      if (i === 0.5) list.push("30 min");
      else {
        const fullHours = Math.floor(i);
        const mins = (i % 1) * 60;
        list.push(`${fullHours} hour${fullHours > 1 ? 's' : ''}${mins > 0 ? ' 30 min' : ''}`);
      }
    }
    return list;
  };

  // 日历逻辑
  const changeMonth = (offset) => {
    setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() + offset, 1));
  };

  const renderCalendarDays = () => {
    const year = viewDate.getFullYear();
    const month = viewDate.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const startOffset = firstDay === 0 ? 6 : firstDay - 1;
    const days = [];
    for (let i = 0; i < startOffset; i++) days.push(<span key={`e-${i}`} className="day-empty"></span>);
    for (let d = 1; d <= daysInMonth; d++) {
      const isSelected = selectedDate.getDate() === d && selectedDate.getMonth() === month && selectedDate.getFullYear() === year;
      const isPast = new Date(year, month, d) < new Date(2026, 1, 10);
      days.push(
        <div key={d} className={`calendar-day ${isSelected ? 'selected' : ''} ${isPast ? 'past' : ''}`}
          onClick={() => !isPast && setSelectedDate(new Date(year, month, d))}>
          {d}
        </div>
      );
    }
    return days;
  };

  const handleBack = () => {
    if (view === 'form') setView('booking');
    else if (view === 'booking') setView('results');
    else if (view === 'filter') setView('results');
    else if (view === 'results') setView('list');
    else navigate('/');
  };

  const handleConfirmBooking = () => {
    setView('list');
    alert('Booking Confirmed!');
  };

  return (
    <div className="meeting-room-container">
      <nav className="top-nav-bar">
        <div className="back-arrow-wrapper" onClick={handleBack}>
          <ChevronLeft size={24} color="#ffffff" strokeWidth={2.5} />
        </div>
        <span className="nav-title">
          {view === 'form' ? "Booking Detail" : (view === 'booking' ? "Meeting Room Details" : (view === 'filter' ? "Searching" : "Meeting Room"))}
        </span>
      </nav>

      <div className="scrollable-area">
        {view === 'list' && (
          /* --- 1. 会议列表视图 --- */
          <div className="content-padding">
            <div className="tabs-header">
              <button 
                className={`tab ${activeTab === 'All' ? 'active' : ''}`} 
                onClick={() => setActiveTab('All')}
              >List All</button>
              <button 
                className={`tab ${activeTab === 'Today' ? 'active' : ''}`} 
                onClick={() => setActiveTab('Today')}
              >Today</button>
              <button 
                className={`tab ${activeTab === 'Week' ? 'active' : ''}`} 
                onClick={() => setActiveTab('Week')}
              >Week</button>
            </div>
            
            <div className="summary-banner">
              <div className="summary-icon"><Calendar size={22} color="#1976d2" /></div>
              <div className="summary-info">
                <h2 style={{ fontSize: "13pt", fontWeight: "bold", margin: 0 }}>
                  {filteredMeetings.length} Meeting Upcoming
                </h2>
                <p style={{ fontSize: "10pt", fontWeight: "bold", margin: "2px 0 0", color: "#000000" }}>2026-02-10, Tuesday</p>
              </div>
            </div>

            <div className="meeting-list">
              {filteredMeetings.map(meeting => (
                <div key={meeting.id} className="details-card">
                  <div className="card-top">
                    <h3>{meeting.title}</h3>
                    <button className="more-options"><MoreVertical size={20} color="#999" /></button>
                  </div>
                  <div className="info-rows">
                    <div className="row"><span className="icon"><User size={18} /></span><span className="text">{meeting.host}</span></div>
                    <div className="row"><span className="icon"><MapPin size={18} /></span><span className="text">{meeting.room}</span></div>
                    <div className="row"><span className="icon"><Calendar size={18} /></span><span className="text">{meeting.date}</span></div>
                    <div className="row"><span className="icon"><Clock size={18} /></span><span className="text">{meeting.time}</span></div>
                  </div>
                  <div className="card-bottom">
                    <div className="attendee-count">
                      <div className="icon-circle"><User size={14} strokeWidth={2.5} /></div>
                      <span className="attendee-number">{meeting.attendees}</span>
                    </div>
                  </div>
                </div>
              ))}
              {filteredMeetings.length === 0 && <p style={{textAlign: 'center', color: '#999', marginTop: '20px'}}>No meetings found.</p>}
            </div>
          </div>
        )}

        {view === 'results' && (
          <div className="search-view-container">
            <button className="search-input-trigger" onClick={() => setView('filter')}>
              <span className="placeholder-text">Search room name...</span><Search size={20} color="#999" />
            </button>
            <div className="search-results-list">
              {[...Array(10)].map((_, i) => (
                <div key={i} className="room-sub-box" onClick={() => { setSelectedRoom(i+1); setView('booking'); }}>
                  <div className="room-box-left"></div>
                  <div className="room-box-right">
                    <h4 className="room-title">Idea Lab {i+1}</h4>
                    <div className="room-details"><div className="detail-item"><User size={14} color="#666" /> <span>8 seats</span></div><div className="detail-item"><Layers size={14} color="#666" /> <span>Level 19</span></div></div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {view === 'filter' && (
          <div className="filter-form-wrapper">
            <p className="form-subtitle">Find A Meeting Room</p>
            <div className="field-group"><label>Date</label>
              <div className="form-field-box" onClick={() => setIsCalendarOpen(true)}>
                <span>{selectedDate.toISOString().split('T')[0]}</span><Calendar size={18} color="#666" />
              </div>
            </div>
            {/* ... 过滤页其他内容保持不变 ... */}
            <div className="form-footer"><button className="capsule-search-btn" onClick={() => setView('results')}>Search Room</button></div>
          </div>
        )}

        {view === 'booking' && (
          <div className="booking-details-container">
            <div className="room-hero-image"><div className="room-label-tag">Idea Lab {selectedRoom}</div></div>
            <div className="room-details-content">
              <h2 className="room-main-title">Signature Teams Room</h2>
              <div className="features-info-card">
                <h3 className="features-title">Room Features</h3>
                <div className="features-grid-layout">
                  {allFeatures.map((f, i) => (
                    <div key={i} className="f-item"><Monitor size={16} color="#00a8ff" /><span>{f}</span></div>
                  ))}
                </div>
              </div>
              <div className="schedule-info-card">
                <h3 className="schedule-header">Please select a time slot</h3>
                <div className="field-group"><div className="form-field-box" onClick={() => setIsCalendarOpen(true)}>
                  <span>{selectedDate.toISOString().split('T')[0]}</span><Calendar size={18} color="#666" />
                </div></div>
                <p className="no-booking-msg">No Booking for the day yet!</p>
                <div className="field-group"><div className="form-field-box select-type">
                  <select value={selectedStartTime} onChange={(e) => { setSelectedStartTime(e.target.value); setSelectedEndTime(''); }}>
                    <option value="">Start Time</option>{fromTimeSlots.map(t => <option key={t} value={t}>{t}</option>)}
                  </select><ChevronDown size={18} color="#666" className="select-arrow" />
                </div></div>
                <div className="field-group"><div className="form-field-box select-type">
                  <select value={selectedDuration} onChange={(e) => setSelectedDuration(e.target.value)} disabled={!selectedStartTime}>
                    <option value="">Length</option>{getAvailableDurations().map(d => <option key={d} value={d}>{d}</option>)}
                  </select><ChevronDown size={18} color="#666" className="select-arrow" />
                </div></div>
              </div>
            </div>
          </div>
        )}

        {view === 'form' && (
          <div className="booking-form-wrapper">
            <div className="form-item"><label>Meeting Host</label>
              <div className="form-field-box select-type static-text"><span>ALAN TAN WAI LOON</span><ChevronDown size={18} color="#666" /></div>
            </div>
            <div className="form-item"><label>Booking Date</label>
              <div className="form-field-box" onClick={() => setIsCalendarOpen(true)}><span>{selectedDate.toISOString().split('T')[0]}</span><Calendar size={18} color="#666" /></div>
            </div>
            <div className="form-row">
              <div className="form-item half"><label>Booking From *</label>
                <div className="form-field-box select-type">
                  <select value={selectedStartTime} onChange={(e) => { setSelectedStartTime(e.target.value); setSelectedEndTime(''); }}>
                    <option value="">Select Time</option>{fromTimeSlots.map(t => <option key={t} value={t}>{t}</option>)}
                  </select><ChevronDown size={18} color="#666" className="select-arrow" />
                </div>
              </div>
              <div className="form-item half"><label>Booking To *</label>
                <div className="form-field-box select-type">
                  <select value={selectedEndTime} onChange={(e) => setSelectedEndTime(e.target.value)} disabled={!selectedStartTime}>
                    <option value="">Select Time</option>{getToTimeSlots().map(t => <option key={t} value={t}>{t}</option>)}
                  </select><ChevronDown size={18} color="#666" className="select-arrow" />
                </div>
              </div>
            </div>
            <div className="form-item"><label>Meeting Title *</label><input type="text" className="form-text-input" placeholder="Enter meeting title" value={meetingTitle} onChange={(e) => setMeetingTitle(e.target.value)} /></div>
            <div className="form-item"><label>Appointment Type</label>
              <div className="form-field-box select-type">
                <select value={appointmentType} onChange={(e) => setAppointmentType(e.target.value)}>
                  <option value="">Select Appointment Type</option><option value="Meeting">Meeting</option><option value="Discussion">Discussion</option><option value="Event">Event</option><option value="Training">Training</option>
                </select><ChevronDown size={18} color="#666" className="select-arrow" />
              </div>
            </div>
            <div className="form-item"><label>Invite Participants</label>
              <div className="invite-input-container">
                <div className="search-participants-box"><input type="text" placeholder="Type to search..." /><Search size={18} color="#999" /></div>
                <button className="add-external-btn" onClick={() => setIsExtModalOpen(true)}><PlusSquare size={28} color="#1a73e8" /></button>
              </div>
              <div className="participant-tags-container">
                {selectedParticipants.map((p, idx) => (
                  <div key={idx} className="name-box-tag"><span className="tag-name">{p.name}</span><X size={14} className="tag-close-icon" onClick={() => setSelectedParticipants(prev => prev.filter((_, i) => i !== idx))} /></div>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>

      {/* --- Modals --- */}
      {isCalendarOpen && (
        <div className="calendar-overlay">
          <div className="calendar-modal">
            <div className="calendar-modal-header"><span>Calendar</span><button className="close-btn" onClick={() => setIsCalendarOpen(false)}>×</button></div>
            <div className="calendar-nav">
              <button className="nav-arrow" onClick={() => changeMonth(-1)}>{'<'}</button>
              <span className="month-year">{viewDate.toLocaleString('default', { month: 'long', year: 'numeric' })}</span>
              <button className="nav-arrow" onClick={() => changeMonth(1)}>{'>'}</button>
            </div>
            <div className="weekday-row">{['Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa', 'Su'].map(d => <span key={d}>{d}</span>)}</div>
            <div className="days-grid">{renderCalendarDays()}</div>
            <div className="calendar-footer"><button className="calendar-confirm-btn" onClick={() => setIsCalendarOpen(false)}>CONFIRM</button></div>
          </div>
        </div>
      )}

      {isExtModalOpen && (
        <div className="calendar-overlay">
          <div className="calendar-modal external-modal">
            <div className="calendar-modal-header"><span>External Participant</span><button className="close-btn" onClick={() => setIsExtModalOpen(false)}><X size={20}/></button></div>
            <div className="modal-body">
              <div className="modal-input-group"><label>Name</label><input type="text" value={extName} onChange={(e) => setExtName(e.target.value)} /></div>
              <div className="modal-input-group"><label>Email</label><input type="email" value={extEmail} onChange={(e) => setExtEmail(e.target.value)} /></div>
            </div>
            <button className="calendar-confirm-btn" onClick={() => { if(extName && extEmail) { setSelectedParticipants([...selectedParticipants, {name: extName, email: extEmail}]); setExtName(''); setExtEmail(''); setIsExtModalOpen(false); } }}>CONFIRM</button>
          </div>
        </div>
      )}

      <div className="search-footer">
        {view === 'list' ? <button className="search-room-btn" onClick={() => setView('results')}><Search size={18} /> Search Room</button> 
        : view === 'booking' ? <button className="book-room-btn" onClick={() => setView('form')}>Book Now</button> 
        : view === 'form' ? <button className="book-room-btn" onClick={handleConfirmBooking}>Confirm</button> : null}
      </div>
    </div>
  );
};

export default MeetingRoom;
